"""The two-part setup card decided on 2026-10-26 (JusPrin: setup-card-opening-message-design-note.md, untracked at the
repo root), drawn three ways from one description of its content:

- card_html(): the canvas board markup (inline styles over the token variables, the way every board is drawn);
- card_spec(): the Design System's screens/*.spec.txt lines for it;
- COMPONENT_JS / COMPONENT_CSS / COMPONENT_DTS: the coded PinnedSetupCard in the Design System bundle.

Above a rule: the person's purpose and the agent's plan, present only when written. Below it: the presets with the
changed-settings count and the All settings link, then the estimates. A warning is an annotation of the line it
contradicts (the plan, the presets, the estimates), one per line, a 14 px triangle-alert glyph in status-warning beside
Label text. Nothing else: no card-wide state but "Agent working", no moment-of-change notes.

Props (a dict for the Python side, the same names in the component):
  purpose, plan, planNote, presets, changed (int), presetsNote, estimate (dict time/material/plate/cost, or a string),
  estimateNote, state, eyebrow ("Setup summary"), historical (bool), footnote, scrolled (bool),
  allSettings (bool, default True), compute (link label beside a string estimate, or None).
"""
import json
import re
import subprocess
import tempfile
from html import escape
from pathlib import Path

HERE = Path(__file__).parent
BOX = 'box-sizing:border-box;flex:none;'
ICONS = json.loads((HERE / 'setup_card_icons.json').read_text())
CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'
FONTS = '/Users/kenneth/Projects/JusPrin/src/slic3r/GUI/JusPrin/WebShared/fonts'


def text(cls, s, color='--text-primary', extra=''):
    return f'<div class="{cls}" style="{BOX}{extra}color:var({color})">{escape(s)}</div>'


def icon(name, size=14, color='--text-secondary', extra=''):
    svg = ICONS[name]
    svg = re.sub(r'width="\d+" height="\d+"', f'width="{size}" height="{size}"', svg, count=1)
    return (f'<span data-icon="{name}" style="{BOX}width:{size}px;height:{size}px;color:var({color});display:inline-block;{extra}">'
            f'{svg}</span>')


def link(label):
    # Button/Link: 26 high, 4 px side padding, Label Bold in action-primary.
    return (f'<div data-c="Button/Link:State=Normal" style="{BOX}height:26px;display:flex;padding:0px var(--space-4) 0px var(--space-4);'
            f'justify-content:center;align-items:center;border-radius:var(--radius-small)">'
            + text('label-bold', label, '--action-primary', 'white-space:nowrap;') + '</div>')


def note(s):
    # The one annotation shape: the glyph in status-warning (the one use of that colour in light mode), Label text.
    return (f'<div data-n="note" style="{BOX}align-self:stretch;display:flex;gap:var(--space-8);align-items:flex-start">'
            + icon('triangle-alert', 14, '--status-warning', 'margin-top:1px;')
            + text('label', s, '--text-primary', 'flex:1 1 0;min-width:0;overflow-wrap:anywhere;') + '</div>')


def facts_text(p):
    parts = [p.get('presets') or '']
    n = p.get('changed') or 0
    if n:
        parts.append(f'{n} setting changed' if n == 1 else f'{n} settings changed')
    return ' · '.join(x for x in parts if x)


def card_html(p, data_n='Pinned Setup Card', standalone=None):
    """The card. standalone=(width, height) draws it as a board root of that size; otherwise it stretches in a column."""
    hist = bool(p.get('historical'))
    accent = '--text-secondary' if hist else '--action-primary'
    parts = []
    head = [text('metadata-bold', p.get('eyebrow') or 'Setup summary', accent, 'flex:1 1 0;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;')]
    if p.get('state'):
        head.append(text('metadata-bold', p['state'], accent, 'white-space:nowrap;'))
    parts.append(f'<div data-n="header" style="{BOX}align-self:stretch;display:flex;gap:var(--space-8);justify-content:space-between;align-items:center">' + ''.join(head) + '</div>')
    words = p.get('purpose') or p.get('plan') or p.get('planNote')
    if words:
        if p.get('purpose'):
            parts.append(text('body-bold', p['purpose'], '--text-primary',
                              'align-self:stretch;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;'))
        if p.get('plan'):
            parts.append(text('label', p['plan'], '--text-primary', 'align-self:stretch;overflow-wrap:anywhere;'))
        if p.get('planNote'):
            parts.append(note(p['planNote']))
        parts.append(f'<hr data-n="rule" style="{BOX}align-self:stretch;width:auto;height:1px;margin:0;border:0;background:var(--border-subtle)">')
    all_settings = p.get('allSettings', True)
    parts.append(f'<div data-n="facts" style="{BOX}align-self:stretch;display:flex;gap:var(--space-8);justify-content:space-between;align-items:center{";min-height:26px" if all_settings else ""}">'
                 + text('label', facts_text(p), '--text-secondary', 'flex:1 1 0;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;')
                 + (link('All settings') if all_settings else '') + '</div>')
    if p.get('presetsNote'):
        parts.append(note(p['presetsNote']))
    est = p.get('estimate')
    if isinstance(est, dict):
        metrics = [(k, est.get(v)) for k, v in (('clock', 'time'), ('package', 'material'), ('grid', 'plate')) if est.get(v)]
        row = ''.join(f'<div data-n="metric" style="{BOX}display:flex;gap:var(--space-8);align-items:center">' + icon(k) + text('label-bold', v, '--text-primary', 'white-space:nowrap;') + '</div>'
                      for k, v in metrics)
        if est.get('cost'):
            row += text('label-bold', est['cost'], '--text-primary', 'white-space:nowrap;')
        parts.append(f'<div data-n="metrics" style="{BOX}align-self:stretch;display:flex;gap:var(--space-12);align-items:center;flex-wrap:wrap;row-gap:4px">{row}</div>')
    elif est:
        compute = p.get('compute')
        parts.append(f'<div data-n="estimate" style="{BOX}align-self:stretch;display:flex;gap:var(--space-8);justify-content:space-between;align-items:center{";min-height:26px" if compute else ""}">'
                     + text('label', est, '--text-secondary', 'flex:1 1 0;min-width:0;overflow-wrap:anywhere;') + (link(compute) if compute else '') + '</div>')
    if p.get('estimateNote'):
        parts.append(note(p['estimateNote']))
    if p.get('footnote'):
        parts.append(text('label', p['footnote'], '--text-secondary', 'align-self:stretch;overflow-wrap:anywhere;'))
    shadow = 'inset 0 -1px 0 0 var(--border-subtle)' + (',var(--elevation-subtle)' if p.get('scrolled') else '')
    size = f'position:relative;width:{standalone[0]}px;height:{standalone[1]}px;' if standalone else 'align-self:stretch;'
    return (f'<div data-c="Pinned Setup Card" data-n="{escape(data_n)}" style="{BOX}{size}display:flex;flex-direction:column;gap:var(--space-4);'
            f'padding:var(--space-12) var(--space-16) var(--space-12) var(--space-16);align-items:flex-start;background:var(--surface-subtle);'
            f'border-radius:0px;box-shadow:{shadow};overflow:hidden">' + ''.join(parts) + '</div>')


def card_spec(p, indent, width=429, name='Pinned Setup Card', root=None):
    """The spec lines (one per layer) for the card. root replaces the first line (a board whose root is the card)."""
    sp = ' ' * indent
    inner = width - 32
    hist = bool(p.get('historical'))
    accent = 'text-secondary' if hist else 'action-primary'
    out = [root or f'{sp}{name}  [instance of Pinned Setup Card]  {width} wide (width fill, height hug) | column, start/start, gap 4, padding 12 16 | fill surface-subtle | shadow inset 0 -1 border-subtle']
    out.append(f'{sp}  header  [frame]  {inner} wide (width fill, height hug) | row, space-between/center, gap 8')
    out.append(f'{sp}    "{p.get("eyebrow") or "Setup summary"}"  [text]  (width fill, height hug) | style metadata-bold | color {accent}')
    if p.get('state'):
        out.append(f'{sp}    "{p["state"]}"  [text]  (width hug, height hug) | style metadata-bold | color {accent}')
    note_lines = lambda s: [f'{sp}  note  [frame]  {inner} wide (width fill, height hug) | row, start/start, gap 8',
                            f'{sp}    triangle-alert  [icon triangle-alert]  14x14 (component-setupCard-iconSize) | color status-warning',
                            f'{sp}    "{s}"  [text]  (width fill, height hug) | style label | color text-primary']
    if p.get('purpose') or p.get('plan') or p.get('planNote'):
        if p.get('purpose'):
            out.append(f'{sp}  "{p["purpose"]}"  [text]  (width fill, height hug, at most 2 lines) | style body-bold | color text-primary')
        if p.get('plan'):
            out.append(f'{sp}  "{p["plan"]}"  [text]  (width fill, height hug) | style label | color text-primary')
        if p.get('planNote'):
            out += note_lines(p['planNote'])
        out.append(f'{sp}  rule  [frame]  {inner}x1 (width fill, height fixed) | fill border-subtle')
    out.append(f'{sp}  facts  [frame]  {inner} wide (width fill, height hug, min 26) | row, space-between/center, gap 8')
    out.append(f'{sp}    "{facts_text(p)}"  [text]  (width fill, height hug, one line, ellipsis) | style label | color text-secondary')
    if p.get('allSettings', True):
        out.append(f'{sp}    "All settings"  [instance of Button/Link (State=Normal)]  26 high (width hug) | style label-bold | color action-primary')
    if p.get('presetsNote'):
        out += note_lines(p['presetsNote'])
    est = p.get('estimate')
    if isinstance(est, dict):
        out.append(f'{sp}  metrics  [frame]  {inner} wide (width fill, height hug) | row, start/center, gap 12, wraps')
        for k, v in (('clock', 'time'), ('package', 'material'), ('grid-3x3', 'plate')):
            if est.get(v):
                out.append(f'{sp}    metric  [frame]  (width hug, height hug) | row, start/center, gap 8')
                out.append(f'{sp}      {k}  [icon {k}]  14x14 (component-setupCard-iconSize) | color text-secondary')
                out.append(f'{sp}      "{est[v]}"  [text]  (width hug, height hug) | style label-bold | color text-primary')
        if est.get('cost'):
            out.append(f'{sp}    "{est["cost"]}"  [text]  (width hug, height hug) | style label-bold | color text-primary')
    elif est:
        out.append(f'{sp}  estimate  [frame]  {inner} wide (width fill, height hug) | row, space-between/center, gap 8')
        out.append(f'{sp}    "{est}"  [text]  (width fill, height hug) | style label | color text-secondary')
        if p.get('compute'):
            out.append(f'{sp}    "{p["compute"]}"  [instance of Button/Link (State=Normal)]  26 high (width hug) | style label-bold | color action-primary')
    if p.get('estimateNote'):
        out += note_lines(p['estimateNote'])
    if p.get('footnote'):
        out.append(f'{sp}  "{p["footnote"]}"  [text]  (width fill, height hug) | style label | color text-secondary')
    return out


_TOKENS = None


def tokens_css(proj):
    global _TOKENS
    if _TOKENS is None:
        _TOKENS = (Path(proj) / 'ds/jusprin/tokens.css').read_text().replace("url('fonts/", f"url('file://{FONTS}/")
    return _TOKENS


def measure(proj, fragment, selector, theme='light'):
    """The natural height of the element `selector` matches, with the fonts loaded, in headless Chrome."""
    page = Path(tempfile.mkdtemp()) / 'm.html'
    page.write_text(f'<!doctype html><html><head><meta charset="utf-8"><style>{tokens_css(proj)}</style><style>body{{margin:0}}</style></head>'
                    f'<body><div data-theme="{theme}" class="body" style="width:max-content;font-family:var(--font-sans)">{fragment}</div>'
                    f'<script>document.fonts.ready.then(()=>{{const e=document.querySelector({json.dumps(selector)});'
                    f'document.body.setAttribute("data-h",Math.ceil(e.getBoundingClientRect().height));}});</script></body></html>')
    dom = subprocess.run([CHROME, '--headless=new', '--disable-gpu', '--no-first-run', f'--user-data-dir={tempfile.mkdtemp()}',
                          '--allow-file-access-from-files', '--virtual-time-budget=3000', '--dump-dom', page.as_uri()],
                         capture_output=True, text=True, timeout=90).stdout
    return int(re.search(r'data-h="(\d+)"', dom).group(1))


def board_file(title, body, width, height):
    """A whole .dc.html board around a body already sized width x height."""
    return f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{escape(title)}</title>
<script src="./support.js"></script>
<link rel="stylesheet" href="ds/jusprin/tokens.css">
</head>
<body>
<x-dc>
<helmet>
<style>
body{{margin:0}}
</style>
</helmet>
{body}
</x-dc>
<script type="text/x-dc" data-dc-script data-props='{{"$preview":{{"width":{width},"height":{height}}}}}'>
class Component extends DCLogic {{
renderVals() {{ return {{}}; }}
}}
</script>
</body>
</html>
'''


def card_board(proj, title, p, theme='light', width=429):
    """A board whose root is the card, at its measured height. Returns (file text, height)."""
    frag = card_html(p, data_n=title)
    h = measure(proj, frag.replace('align-self:stretch;display:flex;flex-direction:column', f'width:{width}px;display:flex;flex-direction:column', 1), '[data-c="Pinned Setup Card"]', theme)
    body = (f'<div data-theme="{theme}" class="body" style="width:{width}px;height:{h}px;position:relative;overflow:hidden;background:#F5F5F5;'
            f'color:var(--text-primary);font-family:var(--font-sans)">{card_html(p, data_n=title, standalone=(width, h))}</div>')
    return board_file(title, body, width, h), h


