input.new_string:
/* A fact line with the link that belongs to it at its end: the presets with
   All settings, or the line that stands in for the estimates with Compute
   estimates. The row aligns on the baseline, so the link's label sits level
   with the text's first line whether the text takes one line or two. */
.current-setup-facts {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  min-height: var(--button-link-height);
}

/* The presets wrap to two lines before they clip, the same clamp as the
   purpose: at the pane's default width a Bambu preset name with a change
   count overflows one line (decided 2026-10-26). The whole of it is in the
   tooltip, and on the All settings panel. */
.current-setup-facts-text {
  flex: 1 1 0;
  min-width: 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  overflow-wrap: anywhere;
  font: var(--font-label);
  color: var(--text-secondary);
}

